import{_ as r,J as i,b as s,e as t,a8 as n,f as o,L as l}from"./chunks/framework.C-MVLAPI.js";const z=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Rasterizers","entity":"GR32_Rasterizers","kind":"Unit","summary":"Provides rasterization algorithms for rendering continuous samplers and coordinate mappings into bitmap pixel buffers.","date":1788572892000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Rasterizers/index.md","filePath":"api/GR32_Rasterizers/index.md","lastUpdated":1788572892000,"timestamp":1788572892000,"datetime":"2026-09-05T01:48:12.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),p={name:"api/GR32_Rasterizers/index.md"};function d(R,e,c,m,u,g){const a=i("ApiMembers");return s(),t("div",null,[e[0]||(e[0]=n('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Rasterizers</code> unit defines the rasterization infrastructure in Graphics32. Rasterizers bridge spatial samplers (<a href="/api/GR32/TCustomSampler/">TCustomSampler</a>) and pixel buffers (<a href="/api/GR32/TCustomBitmap32/">TCustomBitmap32</a>), evaluating surface samples across coordinates and writing formatted pixel colors to the target bitmap.</p><p>Key components in <code>GR32_Rasterizers</code> include:</p><ul><li><strong>Base Class</strong>: <a href="/api/GR32_Rasterizers/TRasterizer/">TRasterizer</a> provides abstract sampling loop mechanics, blend mode handling, and thread-safe persistent property management.</li><li><strong>Regular Rasterization</strong>: <a href="/api/GR32_Rasterizers/TRegularRasterizer/">TRegularRasterizer</a> evaluates samples sequentially scanline by scanline.</li><li><strong>Fractal / Swizzling Rasterization</strong>: <a href="/api/GR32_Rasterizers/TSwizzlingRasterizer/">TSwizzlingRasterizer</a> visits pixel coordinates along space-filling fractal curves to optimize CPU cache locality.</li><li><strong>Progressive Subsampling</strong>: <a href="/api/GR32_Rasterizers/TProgressiveRasterizer/">TProgressiveRasterizer</a> performs multi-step subsampling for fast interactive coarse previews followed by refinement.</li><li><strong>Tesseral &amp; Contour Sampling</strong>: <a href="/api/GR32_Rasterizers/TTesseralRasterizer/">TTesseralRasterizer</a> applies recursive divide-and-conquer block decomposition, while <a href="/api/GR32_Rasterizers/TContourRasterizer/">TContourRasterizer</a> traces pixel contours by color intensity difference.</li><li><strong>Draft Rendering</strong>: <a href="/api/GR32_Rasterizers/TDraftRasterizer/">TDraftRasterizer</a> renders coarse pixel blocks for low-cost live preview.</li><li><strong>Multi-Threaded Rasterization</strong>: Parallel scanline algorithms using system thread pools or worker threads (<a href="/api/GR32_Rasterizers/TMultithreadedRegularRasterizer/">TMultithreadedRegularRasterizer</a>, <a href="/api/GR32_Rasterizers/TParallelRegularRasterizer/">TParallelRegularRasterizer</a>, <a href="/api/GR32_Rasterizers/TTaskRegularRasterizer/">TTaskRegularRasterizer</a>, <a href="/api/GR32_Rasterizers/TThreadRegularRasterizer/">TThreadRegularRasterizer</a>).</li><li><strong>Combination Infrastructure</strong>: <a href="/api/GR32_Rasterizers/TCombineInfo">TCombineInfo</a> and helper routines for configuring drawing mode, master alpha, and pixel combination callbacks during sampling.</li></ul>',4)),o("p",null,[l(a,{type:"members"})])])}const T=r(p,[["render",d]]);export{z as __pageData,T as default};
